package io.github.rebrowser.data;

import static org.junit.Assert.*;
import io.github.rebrowser.browser.*;
import io.github.rebrowser.settings.SettingsRepository;
import io.github.rebrowser.settings.SettingsRepository.NewTabBackground;
import io.github.rebrowser.ui.NewTabView;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.util.*;
import org.junit.Test;

/** Actual HOST filesystem + existing production AEAD/CAS + projection; PRIVATE synthetic key
 * and source fixture only. No install, Android storage/Keystore/worker/View/website execution. */
public final class NewTabSettingsStoreTest {
    static SettingsRepository.Snapshot explicit(long rev){return new SettingsRepository.Snapshot(rev,SearchEngines.Provider.DUCKDUCKGO,false,true,NewTabBackground.WHITE,false);}
    @Test public void bothPresentationFlagsRoundTripWithAllGlobalEngineOptions(){for(SearchEngines.Provider p:SearchEngines.Provider.values())for(NewTabBackground b:NewTabBackground.values())for(boolean recent:new boolean[]{true,false}){SettingsRepository.Snapshot s=new SettingsRepository.Snapshot(5,p,true,false,b,recent);byte[] wire=SettingsRepository.CODEC.encode(s);SettingsRepository.Snapshot d=SettingsRepository.CODEC.decode(ByteBuffer.wrap(wire));assertEquals(p,d.searchProvider());assertEquals(b,d.newTabBackground());assertEquals(recent,d.newTabRecentEnabled());assertTrue(d.desiredEnabled("outlook"));assertFalse(d.desiredEnabled("music"));assertArrayEquals(wire,SettingsRepository.CODEC.encode(d));}}
    @Test public void unrelatedEditsNeverResetNewTabPreferences(){SettingsRepository.Snapshot s=explicit(4);SettingsRepository.Snapshot d=s.withSearch(SearchEngines.Provider.GOOGLE).withEnabled("outlook",true).withEnabled("music",false);assertEquals(7,d.metadataRevision());assertEquals(NewTabBackground.WHITE,d.newTabBackground());assertFalse(d.newTabRecentEnabled());assertEquals(SearchEngines.Provider.GOOGLE,d.searchProvider());assertEquals(NewTabBackground.WHITE,s.newTabBackground());assertEquals(4,s.metadataRevision());}
    @Test public void presentationEditPreservesOtherSettings(){SettingsRepository.Snapshot s=explicit(4),d=s.withNewTab(NewTabBackground.EXCLUSIVE,true);assertEquals(5,d.metadataRevision());assertEquals(SearchEngines.Provider.DUCKDUCKGO,d.searchProvider());assertTrue(d.desiredEnabled("music"));assertFalse(d.desiredEnabled("outlook"));assertEquals(NewTabBackground.EXCLUSIVE,d.newTabBackground());assertTrue(d.newTabRecentEnabled());}
    @Test public void nullBackgroundRevisionOverflowAndUnknownWireValuesReject(){assertThrows(IllegalArgumentException.class,()->explicit(0).withNewTab(null,true));assertThrows(IllegalArgumentException.class,()->new SettingsRepository.Snapshot(Long.MAX_VALUE,SearchEngines.Provider.BING,false,false).withNewTab(NewTabBackground.WHITE,true));byte[] unknown=new NativeRecordCodec.Writer("RBSETT03",200).nonnegative(0).text("bing",16,false).bool(false).bool(false).text("REMOTE_URL",16,false).bool(true).text("https://cn.bing.com/",8192,false).finish();assertThrows(IllegalArgumentException.class,()->SettingsRepository.CODEC.decode(ByteBuffer.wrap(unknown)));}
    @Test public void encryptedFileRoundTripKeepsActualFlagsAndDoesNotExposeLabel()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){f.settings.compareAndWrite(v,explicit(0),f.permit);}try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){SettingsRepository.Snapshot s=v.value(f.permit);assertEquals(SearchEngines.Provider.DUCKDUCKGO,s.searchProvider());assertEquals(NewTabBackground.WHITE,s.newTabBackground());assertFalse(s.newTabRecentEnabled());f.settings.compareAndWrite(v,s.withNewTab(NewTabBackground.EXCLUSIVE,true),f.permit);}try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertEquals(NewTabBackground.EXCLUSIVE,v.value(f.permit).newTabBackground());assertTrue(v.value(f.permit).newTabRecentEnabled());}String bytes=new String(Files.readAllBytes(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef())),java.nio.charset.StandardCharsets.ISO_8859_1);assertFalse(bytes.contains("EXCLUSIVE"));assertFalse(bytes.contains("duckduckgo"));}}
    @Test public void oldUnshippedIncompleteBytesAreRejectedWithoutRepairOrDefaultSeed()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){byte[] old=new NativeRecordCodec.Writer("RBSETT01",200).nonnegative(0).text("bing",16,false).bool(false).bool(false).finish();try(PrivateRecordStore.ReadRecord r=f.records.read(f.ref(OwnedDataCatalog.Family.SETTINGS),f.permit)){f.records.write(r.stamp(),old,f.permit);}byte[] encrypted=Files.readAllBytes(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef()));assertThrows(IllegalArgumentException.class,()->f.settings.read(f.permit));assertArrayEquals(encrypted,Files.readAllBytes(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef())));assertFalse(f.records.hasOwnedIoInFlight());}}
    @Test public void selectedRecentRowUsesFreshActualEncryptedHistoryAfterDeletion()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){f.seedSettings(false);HistoryStore.Page page=new HistoryStore.Page(new HistoryStore.Source(String.format("ws_%032x",1),"source",BrowserModels.Level.TEMPORARY,true),String.format("tab_%032x",1),"real-history","https://example.test/original");try(OwnedDataCatalog.View<HistoryStore.Snapshot> v=f.history.read(f.permit)){f.history.compareAndWrite(v,new HistoryStore.Snapshot(0,false,Collections.emptyList()).addObservedVisit(page,100),f.permit);}SettingsRepository.Snapshot settings;try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){settings=v.value(f.permit);}HistoryStore.Snapshot history=f.history.readCurrent(101,f.permit);NewTabView.Shortcut row=NewTabView.Model.fromNative(settings,history,101).shortcuts().get(0);assertEquals("https://example.test/original",NewTabView.Model.resolveRecent(row,f.history.readCurrent(102,f.permit),102).url());HistoryStore.Entry e=history.entries().get(0);f.history.removeExact(e.id(),e.url(),103,f.permit);assertThrows(IllegalStateException.class,()->NewTabView.Model.resolveRecent(row,f.history.readCurrent(104,f.permit),104));}}
    @Test public void expiryReadReallyRemovesTimedRowBeforeRecentResolution()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){HistoryStore.Page p=new HistoryStore.Page(new HistoryStore.Source(String.format("ws_%032x",1),"source",BrowserModels.Level.TEMPORARY,true),String.format("tab_%032x",1),"t","https://example.test/");try(OwnedDataCatalog.View<HistoryStore.Snapshot> v=f.history.read(f.permit)){f.history.compareAndWrite(v,new HistoryStore.Snapshot(0,false,Collections.emptyList()).addObservedVisit(p,100),f.permit);}NewTabView.Shortcut row=NewTabView.Model.fromNative(new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false),f.history.readCurrent(101,f.permit),101).shortcuts().get(0);long expired=100+HistoryStore.RETENTION_MS;assertTrue(f.history.readCurrent(expired,f.permit).entries().isEmpty());assertThrows(IllegalStateException.class,()->NewTabView.Model.resolveRecent(row,f.history.readCurrent(expired,f.permit),expired));}}
    @Test public void missingSettingsRemainMissingNotDefaultBingBackgroundOrRecentRows()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,v.kind());assertThrows(IllegalStateException.class,()->NewTabView.Model.fromNative(v.value(f.permit),null,0));assertFalse(Files.exists(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef())));}}
}
